package exec

import (
	"fmt"

	"github.com/jokruger/kavun/core"
	"github.com/jokruger/kavun/core/member"
	"github.com/jokruger/kavun/core/value"
	"github.com/jokruger/kavun/errs"
)

// exec.command's members: one function per member, each declared by the //kavun:member directive in its doc comment.
// The table, commandMethods, and the member entries of docs/reference/types/exec_command.md (alphabetical, so the order
// here is free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a directive or a doc comment.

// Report truthiness: a command is always truthy.
//
//kavun:member is_true pure () -> bool
func commandIsTrue(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	t, err := core.ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return core.Undefined, err
	}
	return core.BoolValue(t), nil
}

// Render the command per the [format mini-language](../../format_mini_language.md).
//
//kavun:member format pure ([spec]) -> string
func commandFormat(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	return core.FormatWithSpec(v, id, args)
}

// Answer the command itself.
//
//kavun:member copy pure () -> exec.command
func commandCopy(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	return v, nil
}

// Answer the command itself; see [`copy`](#copy).
//
//kavun:member freeze pure () -> exec.command
func commandFreeze(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	return v, nil
}

func commandContext(id member.ID) string {
	return "exec.command." + id.String()
}

// commandDone answers undefined for a statement-like member, or the io error.
func commandDone(id member.ID, err error) (core.Value, error) {
	if err != nil {
		return core.Undefined, errs.NewIOError(commandContext(id), err)
	}
	return core.Undefined, nil
}

// Run the command and wait for it; raises `io` if it cannot start or ends with a failure status.
//
//kavun:member run impure () -> undefined
func commandRun(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	return commandDone(id, CommandOf(v).Run())
}

// Start the command without waiting for it.
//
//kavun:member start impure () -> undefined
func commandStart(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	return commandDone(id, CommandOf(v).Start())
}

// Wait for a started command to end; see [`start`](#start).
//
//kavun:member wait impure () -> undefined
func commandWait(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	return commandDone(id, CommandOf(v).Wait())
}

// Run the command and answer its stdout, as `bytes`.
//
//kavun:member output impure () -> bytes
func commandOutput(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	out, err := CommandOf(v).Output()
	if err != nil {
		return core.Undefined, errs.NewIOError(commandContext(id), err)
	}
	return core.NewBytesValue(out, false), nil
}

// Run the command and answer its stdout and stderr together, as `bytes`; see [`output`](#output).
//
//kavun:member combined_output impure () -> bytes
func commandCombinedOutput(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	out, err := CommandOf(v).CombinedOutput()
	if err != nil {
		return core.Undefined, errs.NewIOError(commandContext(id), err)
	}
	return core.NewBytesValue(out, false), nil
}

// Set the program path; configure before running.
//
//kavun:member set_path impure (p) -> undefined
func commandSetPath(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	s, ok := args[0].AsString()
	if !ok {
		return core.Undefined, errs.NewInvalidArgumentTypeError(commandContext(id), "first", "string(compatible)", args[0].TypeName())
	}
	CommandOf(v).Path = s
	return core.Undefined, nil
}

// Set the working directory; configure before running.
//
//kavun:member set_dir impure (d) -> undefined
func commandSetDir(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	s, ok := args[0].AsString()
	if !ok {
		return core.Undefined, errs.NewInvalidArgumentTypeError(commandContext(id), "first", "string(compatible)", args[0].TypeName())
	}
	CommandOf(v).Dir = s
	return core.Undefined, nil
}

// Set the environment, an array of `"K=V"` strings; configure before running.
//
//kavun:member set_env impure (env) -> undefined
func commandSetEnv(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	env, err := StringsArg(commandContext(id), "first", args[0])
	if err != nil {
		return core.Undefined, err
	}
	CommandOf(v).Env = env
	return core.Undefined, nil
}

// Answer the started command's [`exec.process`](exec_process.md); before `start()` it raises `invalid_value`.
//
//kavun:member process impure () -> exec.process
func commandProcess(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	p := CommandOf(v).Process
	if p == nil {
		return core.Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) the command has not been started", commandContext(id)))
	}
	return NewProcessValue(p), nil
}

// StringsArg reads an array of strings argument (a command's argv or environment).
func StringsArg(name, pos string, a core.Value) ([]string, error) {
	if a.Type != value.Array {
		return nil, errs.NewInvalidArgumentTypeError(name, pos, "array(string)", a.TypeName())
	}
	elems := (*core.Array)(a.Ptr).Elements
	out := make([]string, 0, len(elems))
	for i, e := range elems {
		s, ok := e.AsString()
		if !ok {
			return nil, errs.NewInvalidArgumentTypeError(name, fmt.Sprintf("%s[%d]", pos, i), "string(compatible)", e.TypeName())
		}
		out = append(out, s)
	}
	return out, nil
}
